package com.ecole.gestion_scolaire.finance.service;

import com.ecole.gestion_scolaire.common.dto.PageResponse;
import com.ecole.gestion_scolaire.finance.dto.discount.*;
import com.ecole.gestion_scolaire.finance.entity.*;
import com.ecole.gestion_scolaire.finance.enums.*;
import com.ecole.gestion_scolaire.finance.exception.*;
import com.ecole.gestion_scolaire.finance.integration.RegistrationPaymentService;
import com.ecole.gestion_scolaire.finance.repository.*;
import com.ecole.gestion_scolaire.registration.repository.*;
import com.ecole.gestion_scolaire.student.repository.StudentGuardianRepository;
import org.springframework.data.domain.*;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal; import java.math.RoundingMode; import java.time.*; import java.util.*;

@Service
public class DiscountService {
 private final StudentDiscountRepository repo; private final StudentDiscountAdjustmentRepository adjustments;
 private final StudentChargeRepository charges; private final StudentEnrollmentRepository enrollments; private final RegistrationCaseRepository registrations; private final FeeTypeRepository fees;
 private final DiscountCalculationService calculator; private final PaymentAllocationService allocations; private final FamilyCreditService credits;
 private final StudentGuardianRepository guardianLinks; private final CurrentFinanceAccountService current; private final RegistrationPaymentService registrationPayments;
 public DiscountService(StudentDiscountRepository r,StudentDiscountAdjustmentRepository a,StudentChargeRepository c,StudentEnrollmentRepository e,RegistrationCaseRepository rc,FeeTypeRepository f,DiscountCalculationService calc,PaymentAllocationService pa,FamilyCreditService fc,StudentGuardianRepository gl,CurrentFinanceAccountService cu,RegistrationPaymentService rp){repo=r;adjustments=a;charges=c;enrollments=e;registrations=rc;fees=f;calculator=calc;allocations=pa;credits=fc;guardianLinks=gl;current=cu;registrationPayments=rp;}

 @Transactional public StudentDiscountResponse create(StudentDiscountRequest r){
   boolean enrollment=r.studentEnrollmentId()!=null, registration=r.registrationCaseId()!=null;
   if(enrollment==registration) throw new FinanceBusinessException("Indiquez soit une scolarisation, soit un dossier d'inscription.");
   if(enrollment) enrollments.findById(r.studentEnrollmentId()).orElseThrow(()->new FinanceNotFoundException("Scolarisation introuvable."));
   if(registration) registrations.findById(r.registrationCaseId()).orElseThrow(()->new FinanceNotFoundException("Dossier d'inscription introuvable."));
   if(r.feeTypeId()!=null&&!fees.existsById(r.feeTypeId()))throw new FinanceNotFoundException("Type de frais introuvable.");
   validateType(r.discountType(),r.value()); if(r.endDate()!=null&&r.endDate().isBefore(r.startDate()))throw new FinanceBusinessException("La date de fin est antérieure à la date de début.");
   var x=new StudentDiscount(); x.setStudentEnrollmentId(r.studentEnrollmentId()); x.setRegistrationCaseId(r.registrationCaseId()); x.setFeeTypeId(r.feeTypeId()); x.setDiscountType(r.discountType().toUpperCase(Locale.ROOT)); x.setValue(r.value()); x.setStartDate(r.startDate()); x.setEndDate(r.endDate()); x.setReason(r.reason()); x.setStatus(DiscountStatus.PENDING_APPROVAL.name()); x.setCreatedBy(current.id()); x=repo.save(x);
   if(canApprove()) return approve(x.getId()); return toResponse(x);
 }
 @Transactional(readOnly=true) public PageResponse<StudentDiscountResponse> search(String status,Long enrollmentId,Long registrationCaseId,int page,int size){var p=PageRequest.of(Math.max(0,page),Math.min(100,Math.max(1,size)),Sort.by("createdAt").descending()); Page<StudentDiscount>x=enrollmentId!=null?repo.findByStudentEnrollmentId(enrollmentId,p):registrationCaseId!=null?repo.findByRegistrationCaseId(registrationCaseId,p):status!=null&&!status.isBlank()?repo.findByStatus(status,p):repo.findAll(p); return PageResponse.from(x.map(this::toResponse));}
 @Transactional public StudentDiscountResponse approve(Long id){var x=get(id);if(!DiscountStatus.PENDING_APPROVAL.name().equals(x.getStatus()))throw new FinanceBusinessException("Cette réduction n'est plus en attente de validation.");x.setStatus(DiscountStatus.APPROVED.name());x.setApprovedBy(current.id());x.setApprovedAt(OffsetDateTime.now());repo.save(x);if(x.getRegistrationCaseId()!=null)applyRegistration(x);else applyEnrollment(x.getStudentEnrollmentId(),x.getId(),null);x.setAppliedAt(OffsetDateTime.now());return toResponse(repo.save(x));}
 @Transactional public StudentDiscountResponse reject(Long id,String reason){var x=get(id);if(!DiscountStatus.PENDING_APPROVAL.name().equals(x.getStatus()))throw new FinanceBusinessException("Cette réduction n'est plus en attente de validation.");x.setStatus(DiscountStatus.REJECTED.name());x.setRejectedBy(current.id());x.setRejectedAt(OffsetDateTime.now());x.setRejectionReason(reason);return toResponse(repo.save(x));}
 @Transactional public DiscountApplicationResponse reapplyEnrollment(Long enrollmentId){enrollments.findById(enrollmentId).orElseThrow(()->new FinanceNotFoundException("Scolarisation introuvable."));return applyEnrollment(enrollmentId,null,null);}

 private DiscountApplicationResponse applyRegistration(StudentDiscount d){int count=0;BigDecimal total=BigDecimal.ZERO,credit=BigDecimal.ZERO;for(var c:charges.findByRegistrationCaseIdOrderByDueDateAscIdAsc(d.getRegistrationCaseId())){if("CANCELLED".equals(c.getStatus()))continue;if(d.getFeeTypeId()!=null&&!d.getFeeTypeId().equals(c.getFeeTypeId()))continue;LocalDate date=c.getBillingPeriodStart()!=null?c.getBillingPeriodStart():c.getDueDate();if(date!=null&&(date.isBefore(d.getStartDate())||(d.getEndDate()!=null&&date.isAfter(d.getEndDate()))))continue;BigDecimal oldDisc=nz(c.getDiscountAmount()),oldFinal=nz(c.getFinalAmount());BigDecimal newDisc=discountAmount(d.getDiscountType(),d.getValue(),c.getOriginalAmount());BigDecimal newFinal=c.getOriginalAmount().subtract(newDisc).max(BigDecimal.ZERO);BigDecimal settled=allocations.paidForCharge(c.getId());BigDecimal extraCredit=settled.subtract(newFinal).max(BigDecimal.ZERO).subtract(settled.subtract(oldFinal).max(BigDecimal.ZERO)).max(BigDecimal.ZERO);c.setDiscountAmount(newDisc);c.setFinalAmount(newFinal);c.setStatus(chargeStatus(newFinal,settled));charges.save(c);var adj=new StudentDiscountAdjustment();adj.setStudentDiscountId(d.getId());adj.setStudentChargeId(c.getId());adj.setPreviousDiscountAmount(oldDisc);adj.setNewDiscountAmount(newDisc);adj.setPreviousFinalAmount(oldFinal);adj.setNewFinalAmount(newFinal);adj.setCreditCreated(extraCredit);adj.setAppliedBy(current.id());adjustments.save(adj);if(extraCredit.signum()>0){var reg=registrations.findById(d.getRegistrationCaseId()).orElseThrow();credits.createFromDiscount(reg.getGuardian().getId(),d.getId(),extraCredit);credit=credit.add(extraCredit);}count++;total=total.add(oldFinal.subtract(newFinal).max(BigDecimal.ZERO));}if(count==0)throw new FinanceBusinessException("Aucun frais correspondant n'a été trouvé sur ce dossier d'inscription.");registrationPayments.refresh(d.getRegistrationCaseId());return new DiscountApplicationResponse(count,total,credit);}
 private DiscountApplicationResponse applyEnrollment(Long enrollmentId,Long sourceDiscountId,Long sourceRuleId){int count=0;BigDecimal total=BigDecimal.ZERO,credit=BigDecimal.ZERO;Long uid=current.id();for(var c:charges.findByStudentEnrollmentIdOrderByDueDateAscIdAsc(enrollmentId)){if("CANCELLED".equals(c.getStatus()))continue;LocalDate date=c.getBillingPeriodStart()!=null?c.getBillingPeriodStart():c.getDueDate();var calc=calculator.calculate(enrollmentId,c.getFeeTypeId(),c.getOriginalAmount(),date);BigDecimal newDisc=calc.discountAmount(),oldDisc=c.getDiscountAmount(),oldFinal=c.getFinalAmount(),newFinal=c.getOriginalAmount().subtract(newDisc).max(BigDecimal.ZERO);if(newFinal.compareTo(oldFinal)==0&&newDisc.compareTo(oldDisc)==0)continue;BigDecimal settled=allocations.paidForCharge(c.getId()),oldExcess=settled.subtract(oldFinal).max(BigDecimal.ZERO),newExcess=settled.subtract(newFinal).max(BigDecimal.ZERO),extraCredit=newExcess.subtract(oldExcess).max(BigDecimal.ZERO);c.setDiscountAmount(newDisc);c.setFinalAmount(newFinal);c.setStatus(chargeStatus(newFinal,settled));charges.save(c);var adj=new StudentDiscountAdjustment();adj.setStudentDiscountId(sourceDiscountId!=null?sourceDiscountId:calc.studentDiscountId());adj.setDiscountRuleId(sourceRuleId!=null?sourceRuleId:calc.discountRuleId());adj.setStudentChargeId(c.getId());adj.setPreviousDiscountAmount(oldDisc);adj.setNewDiscountAmount(newDisc);adj.setPreviousFinalAmount(oldFinal);adj.setNewFinalAmount(newFinal);adj.setCreditCreated(extraCredit);adj.setAppliedBy(uid);adjustments.save(adj);if(extraCredit.signum()>0){Long gid=guardianForEnrollment(enrollmentId);credits.createFromDiscount(gid,sourceDiscountId!=null?sourceDiscountId:calc.studentDiscountId(),extraCredit);credit=credit.add(extraCredit);}count++;total=total.add(oldFinal.subtract(newFinal).max(BigDecimal.ZERO));}return new DiscountApplicationResponse(count,total,credit);}
 private String chargeStatus(BigDecimal finalAmount,BigDecimal settled){if(nz(finalAmount).compareTo(BigDecimal.ZERO)<=0)return "PAID";if(nz(settled).compareTo(finalAmount)>=0)return "PAID";if(nz(settled).signum()>0)return "PARTIALLY_PAID";return "DUE";}
 private BigDecimal discountAmount(String type,BigDecimal value,BigDecimal original){BigDecimal a=switch(DiscountType.valueOf(type)){case PERCENTAGE->original.multiply(value).divide(new BigDecimal("100"),2,RoundingMode.HALF_UP);case FIXED_AMOUNT->value;case NEW_AMOUNT->original.subtract(value);};return a.max(BigDecimal.ZERO).min(original);}
 private BigDecimal nz(BigDecimal v){return v==null?BigDecimal.ZERO:v;}
 private Long guardianForEnrollment(Long enrollmentId){var e=enrollments.findById(enrollmentId).orElseThrow();var links=guardianLinks.findByStudentIdOrderByIdAsc(e.getStudent().getId()).stream().filter(x->x.isActive()&&x.isFinancialResponsible()).toList();if(links.isEmpty())links=guardianLinks.findByStudentIdOrderByIdAsc(e.getStudent().getId()).stream().filter(x->x.isActive()).toList();if(links.isEmpty())throw new FinanceBusinessException("Aucun responsable actif trouvé pour créer l'avoir familial.");return links.get(0).getGuardian().getId();}
 private StudentDiscount get(Long id){return repo.findById(id).orElseThrow(()->new FinanceNotFoundException("Réduction introuvable : "+id));}
 private boolean canApprove(){var a=SecurityContextHolder.getContext().getAuthentication();return a!=null&&a.getAuthorities().stream().anyMatch(x->"REDUCTION_VALIDER".equals(x.getAuthority())||"ROLE_ADMIN".equals(x.getAuthority()));}
 private void validateType(String t,BigDecimal v){try{var type=DiscountType.valueOf(t.toUpperCase(Locale.ROOT));if(v==null||v.signum()<0)throw new Exception();if(type==DiscountType.PERCENTAGE&&v.compareTo(new BigDecimal("100"))>0)throw new FinanceBusinessException("Le pourcentage ne peut pas dépasser 100 %. ");}catch(IllegalArgumentException e){throw new FinanceBusinessException("Type de réduction invalide. Utilisez PERCENTAGE, FIXED_AMOUNT ou NEW_AMOUNT.");}catch(Exception e){throw new FinanceBusinessException("Valeur de réduction invalide.");}}
 private StudentDiscountResponse toResponse(StudentDiscount x){return new StudentDiscountResponse(x.getId(),x.getStudentEnrollmentId(),x.getRegistrationCaseId(),x.getFeeTypeId(),x.getDiscountType(),x.getValue(),x.getStartDate(),x.getEndDate(),x.getReason(),x.getStatus(),x.getCreatedBy(),x.getCreatedAt(),x.getApprovedBy(),x.getApprovedAt(),x.getRejectedBy(),x.getRejectedAt(),x.getRejectionReason(),x.getAppliedAt());}
}
